"""T53 (artefato 9HaJSD): ?cena = só o cenário vivo, sem nada por cima (fundo da tela de entrar do painel); o painel manda a faixa livre por postMessage e o site avisa quando o cenário está pronto.
Uso: python _patch_t53.py site"""
import sys, pathlib, json
I = pathlib.Path(sys.argv[1]) / "index.html"; s = I.read_text(encoding="utf-8")
TAG = "_patch_t53.py"
assert ("/*" + TAG + "*/") not in s, "já aplicado"
HUNKS = json.loads("[{\"t\": \"replace\", \"old\": \".scene-loop { position: absolute; display: block; max-width: none; pointer-events: none; object-fit: fill; }\", \"new\": \"/* 13b (John): ?cena = s\u00f3 o cen\u00e1rio vivo, sem nada por cima (fundo do login do painel) */\\nhtml.cena body > :not(#scene) { display: none !important; }\\nhtml.cena, html.cena body { overflow: hidden; }\\n.scene-loop { position: absolute; display: block; max-width: none; pointer-events: none; object-fit: fill;  -webkit-mask-image: linear-gradient(transparent, #000 24px, #000 calc(100% - 70px), transparent); mask-image: linear-gradient(transparent, #000 24px, #000 calc(100% - 70px), transparent); }   /* 13b: as bordas do v\u00eddeo somem na foto de tr\u00e1s */\", \"pre\": \"html { scrollbar-width: none; } html::-webkit-scrollbar { display: none; width: 0; height: 0; }\", \"post\": \"html.no-gl .scene { background: linear-gradient(90deg, #cdd8db 0%, #c7ecef 30%, #2baefa 50%, #008ff3 70%, #0089da 100%); }   /* 12j: acima do v\u00eddeo (c\u00e9u a mais no PC) a cor do alto do c\u00e9u */\", \"k\": 2}, {\"t\": \"replace\", \"old\": \"<script>document.documentElement.classList.add('intro');try{history.scrollRestoration='manual'}catch(e){}</script>\", \"new\": \"<script>document.documentElement.classList.add('intro');if(/[?&]cena\\\\b/.test(location.search))document.documentElement.classList.add('cena');try{history.scrollRestoration='manual'}catch(e){}</script>\", \"pre\": \"<body>\", \"post\": \"<svg width=\\\"0\\\" height=\\\"0\\\" style=\\\"position:absolute\\\" aria-hidden=\\\"true\\\" focusable=\\\"false\\\">\", \"k\": 5}, {\"t\": \"insert\", \"old\": \"\", \"new\": \"  if (CENA) return;\", \"pre\": \"function track(name, data = {}) {\", \"post\": \"  const payload = Object.assign({ event: 'ct_' + name, ms: Math.round(performance.now() - T0) }, data);\", \"k\": 21}, {\"t\": \"insert\", \"old\": \"\", \"new\": \"    off() { if (!on_) return; on_ = false; root.classList.remove('st-copy'); if (cv2) cv2.remove(); cv2 = ctx = null; },\", \"pre\": \"    },\", \"post\": \"    get on_() { return on_; }\", \"k\": 34}, {\"t\": \"insert\", \"old\": \"\", \"new\": \"const CB = { top: 12, bottom: 0 };\\nif (CENA) addEventListener('message', e => { const d = e.data; if (d && d.ct && d.band) { CB.top = +d.band[0] || 12; CB.bottom = +d.band[1] || 0; layoutFrame(); } });\", \"pre\": \"// \u00e1rea livre para o \u00f4nibus = entre o cabe\u00e7alho do palco e o seletor\", \"post\": \"function layoutFrame() {\", \"k\": 35}, {\"t\": \"insert\", \"old\": \"\", \"new\": \"  if (CENA) { const t = CB.top, b = CB.bottom || innerHeight * 0.32; World.setBand(innerHeight, t, Math.max(t + 80, b)); if (window.__noGlBus) window.__noGlBus(current.id); return; }\", \"pre\": \"  if (typeof World === 'undefined' || !World.setBand || root.classList.contains('in-tour')) return;\", \"post\": \"  const H = stageMax || 1;\", \"k\": 36}, {\"t\": \"replace\", \"old\": \"    await Promise.race([preloadAll, new Promise(r => setTimeout(r, 8000))]);   // v23: fotos e fontes prontas antes dos \u00f4nibus\\n    SITE.fleet.filter(b => b !== current).forEach(preloadPhotos);\", \"new\": \"    if (!CENA) { await Promise.race([preloadAll, new Promise(r => setTimeout(r, 8000))]);   // v23: fotos e fontes prontas antes dos \u00f4nibus\\n    SITE.fleet.filter(b => b !== current).forEach(preloadPhotos); }\", \"pre\": \"    if (!worldOK) throw new Error('sem WebGL2');\", \"post\": \"    World.on('arrived', id => { track('bus_arrived', { bus: id }); endIntro('chegou'); });\", \"k\": 44}]")
for h in HUNKS:   # trechos do artefato 9HaJSD (17/11), aplicados sobre o nosso site
    if h["t"] == "insert":
        a = h["pre"] + "\n" + h["post"]; assert s.count(a) == 1, (h["k"], s.count(a), a[:80])
        s = s.replace(a, h["pre"] + "\n" + h["new"] + "\n" + h["post"])
    else:
        assert s.count(h["old"]) == 1, (h["k"], s.count(h["old"]), h["old"][:80])
        s = s.replace(h["old"], h["new"])
def rep(a, b):
    global s; assert s.count(a) == 1, (s.count(a), a[:80]); s = s.replace(a, b)

s = s.replace("</html>", "<!--/*" + TAG + "*/-->\n</html>", 1) if "</html>" in s else s + "\n<!--/*" + TAG + "*/-->\n"
I.write_text(s, encoding="utf-8", newline="\n"); print(TAG, "aplicado:", len(HUNKS), "trechos")
